package org.apache.commons.math3.optimization.fitting;

import org.apache.commons.math3.exception.MathIllegalStateException;
import org.apache.commons.math3.optimization.fitting.HarmonicFitter;
import org.apache.commons.math3.optimization.fitting.WeightedObservedPoint;
import org.junit.Test;
import static org.junit.Assert.*;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Comparator;

public class AgentBRT_Math_25_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        HarmonicFitter fitter = new HarmonicFitter(null);

        // Create observations that will lead to c2 being zero
        WeightedObservedPoint[] observations = new WeightedObservedPoint[] {
            new WeightedObservedPoint(1.0, 0.0, 1.0),
            new WeightedObservedPoint(1.0, 1.0, 1.0),
            new WeightedObservedPoint(1.0, 2.0, 1.0),
            new WeightedObservedPoint(1.0, 3.0, 1.0),
            new WeightedObservedPoint(1.0, 4.0, 1.0)
        };

        // Sort observations manually using an anonymous comparator class
        Arrays.sort(observations, new Comparator<WeightedObservedPoint>() {
            public int compare(WeightedObservedPoint o1, WeightedObservedPoint o2) {
                return Double.compare(o1.getX(), o2.getX());
            }
        });

        try {
            // Use reflection to access the private method guessAOmega
            Method guessAOmega = HarmonicFitter.class.getDeclaredMethod("guessAOmega");
            guessAOmega.setAccessible(true);

            // This should trigger the bug
            guessAOmega.invoke(fitter);
            fail("Expected MathIllegalStateException due to zero denominator");
        } catch (MathIllegalStateException e) {
            // Expected exception
        } catch (Exception e) {
            fail("Unexpected exception: " + e.getMessage());
        }
    }
}

